	if err := memcached.Start(c.MemcachedHost, c.MemcachedPort); err != nil {
		return errors.Wrap(err, "failed to start memcached")
	}

	// Wait for memcached to be ready.
	if err := memcached.WaitForReady(c.MemcachedHost, c.MemcachedPort); err != nil {
		return errors.Wrap(err, "memcached failed to become ready")
	}

	// Prepare the command arguments for mutilate.
	args := []string{
