// pool is a pool of matrices used to reduce allocations.
var pool = &matrixPool{
	pool: make(map[int][][]float64),
	mu:   sync.RWMutex{},
}

// matrixPool holds a pool of matrices.
type matrixPool struct {
	pool map[int][][]float64
	mu   sync.RWMutex
}

// get returns a matrix of size m×n from the pool, or creates a new one if none is available.
func (p *matrixPool) get(m, n int) [][]float64 {
	p.mu.RLock()
	if matrices, ok := p.pool[m*n]; ok && len(matrices) > 0 {
		mat := matrices[len(matrices)-1]
		p.pool[m*n] = matrices[:len(matrices)-1]
		p.mu.RUnlock()
		return mat
	}
	p.mu.RUnlock()

	// No matrix available, create a new one.
	return make([][]float64, m)
}

// put returns a matrix to the pool for reuse.
