	//
	// The result is a list of lines with their authorship. We traverse the graph
	// in reverse order (from the most recent commit to the oldest) and assign
	// the commit that actually introduced the line (or last modified it) to each line.
	//
	// This is done by walking through the lines and using the `assignOrigin` method
	// which resolves the origin commit for each line.
	for i, line := range finalLines {
		if line == "" {
			// Skip empty lines, they don't have an author.
			continue
		}

		// Retrieve the line's origin from the graph
		commit, err := b.assignOrigin(i)
		if err != nil {
			return nil, err
		}

		// Create a new Line with the line content and the authorship
		b.Result.Lines = append(b.Result.Lines, &Line{
			Content: line,
			Commit:  commit,
		})
	}

	// Set final metadata
	b.Result.Path = b.path
	b.Result.Rev = b.fRev.Hash

	return b

